import mods.avogadro.Molecules;
import mods.avogadro.RegistrationJob;

// Common startup. ZenScript geometry preparation is synchronous; there is no worker-delivery facade here.
val water = Molecules.molecule("example:water").smiles("[H]O[H]");
// Publication has an observable, cancellable queue independently of how the geometry was prepared.
val owned = Molecules.transaction("example_prepared").replaceAll().register(water).commit();
owned.onComplete(function(outcome) {
    if (outcome.state == "failed") print("Registration rejected: " + outcome.failure);
    else print("Registration state: " + outcome.state);
});
function cancelPending(job as RegistrationJob) as bool { return job.cancel(); }
// Teardown calls owned.close(). Cancellation is accepted only before application starts;
// it never claims to undo an already published transaction. Kotlin/Scala/Java CPU jobs use PreparationScope.
